// Build lookup maps for fast resolution
const byId = new Map<string, LibraryEntry>(
  LIBRARY_REGISTRY.map((l) => [l.id, l]),
);

const byAlias = new Map<string, LibraryEntry>();
// Pass 1: explicit names and aliases own their keys unconditionally.
for (const entry of LIBRARY_REGISTRY) {
  for (const alias of [entry.name.toLowerCase(), ...entry.aliases]) {
    byAlias.set(alias.toLowerCase(), entry);
  }
}
// Pass 2: npm/pypi package names auto-register only when the key is free.
// Last-write-wins here silently hijacked explicit aliases — e.g. the Python
// "langchain" pypiPackage overwrote the "langchain" alias declared by
// langchain-ai/langchainjs, resolving JS lookups to the wrong library.
for (const entry of LIBRARY_REGISTRY) {
  for (const pkg of [entry.npmPackage, entry.pypiPackage]) {
    if (!pkg) continue;
    const key = pkg.toLowerCase();
    if (!byAlias.has(key)) byAlias.set(key, entry);
  }
}

export function lookupById(id: string): LibraryEntry | undefined {
  return byId.get(id);
}

export function lookupByAlias(name: string): LibraryEntry | undefined {
  return byAlias.get(name.toLowerCase());
}

export function fuzzySearch(query: string, limit = 5, minScore = 1): LibraryEntry[] {
  const q = query.toLowerCase();
  const scored: Array<{ entry: LibraryEntry; score: number }> = [];

  for (const entry of LIBRARY_REGISTRY) {
    let score = 0;
    const nameL = entry.name.toLowerCase();

    if (nameL === q) score += 100;
    else if (nameL.startsWith(q)) score += 60;
    else if (nameL.includes(q)) score += 30;

    for (const alias of entry.aliases) {
      const a = alias.toLowerCase();
      if (a === q) score += 90;
      else if (a.startsWith(q)) score += 50;
      else if (a.includes(q)) score += 20;
    }

    if (entry.npmPackage?.toLowerCase().includes(q)) score += 15;
    if (entry.tags.some((t) => t.includes(q))) score += 10;

    // minScore default 1 == prior score>0 (scores are integers); detectLibrary
    // passes 20 so tag-only (10) / npm-only (15) matches cannot misroute.
    if (score >= minScore) scored.push({ entry, score });
  }

  return scored
    .sort((a, b) => {
      if (b.score !== a.score) return b.score - a.score;
      // Deterministic tie-break: shorter/more specific name wins, then
      // alphabetical by id — never incidental registry array order.
      if (a.entry.name.length !== b.entry.name.length) {
        return a.entry.name.length - b.entry.name.length;
      }
      return a.entry.id.localeCompare(b.entry.id);
    })
    .slice(0, limit)
    .map((s) => s.entry);
}
